ALTER TABLE "kublai_part_definition" ADD COLUMN "bulkUnit" varchar(32);
ALTER TABLE "kublai_part_definition" ADD COLUMN "individualUnit" varchar(32);
-- Existing populated contents were explicitly reviewed as piece packs.
UPDATE "kublai_part_definition" SET "individualUnit" = 'pcs', "bulkUnit" = CASE
 WHEN "displayName" ~* '\mbox\M' THEN 'box'
 WHEN "displayName" ~* '\m(pack|pk)\M|[0-9]pk\M' THEN 'pack'
 ELSE NULL END
